  height: 1px;
  background: linear-gradient(90deg, rgba(var(--color-foreground), 0.28) 0%, rgba(var(--color-foreground), 0.08) 70%, rgba(var(--color-foreground), 0) 100%);
}

.category-icons__trust {
  display: grid;
  gap: 0.75rem;
  margin: 0 0 1.6rem;
  grid-template-columns: repeat(1, minmax(0, 1fr));
}

.category-icons__trust-item {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.6rem;
  min-height: 4rem;
  padding: 0.95rem 1.25rem;
  border-radius: 999px;
  border: 1px solid rgba(var(--color-foreground), 0.1);
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 12px 28px rgba(var(--color-foreground), 0.06);
  color: inherit;
  font-size: 1.14rem;
  line-height: 1.3;
  font-weight: 700;
  text-align: center;
}

.category-icons__trust-icon {
  display: inline-flex;
  flex-shrink: 0;
  color: rgb(var(--color-foreground));
  opacity: 0.72;
}

.category-icons__scroll {
  display: flex;
  gap: 1.2rem;
  overflow-x: auto;
  scroll-snap-type: x proximity;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  list-style: none;
  margin: 0;
  padding: 0 1.5rem 0.7rem;
  scroll-padding-inline: 1.5rem;
}

.category-icons__scroll::-webkit-scrollbar {
  display: none;
}

.category-icons__item {
  flex: 0 0 auto;
  width: min(76vw, 34rem);
  scroll-snap-align: start;
  list-style: none;
}

.category-icons__link {
  position: relative;
  display: block;
  width: 100%;
  text-decoration: none;
  color: inherit;
  border-radius: 2rem;
  overflow: hidden;
  background: rgba(32, 22, 19, 0.04);
  box-shadow: 0 18px 42px rgba(32, 22, 19, 0.12);
  isolation: isolate;
}

.category-icons__link::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 3;
  border: 1px solid rgba(255, 255, 255, 0.28);
  border-radius: inherit;
  pointer-events: none;
}

.category-icons__link::after {
  content: '';
  position: absolute;
  inset: auto 0 0;
  z-index: 1;
  height: 58%;
  background: linear-gradient(180deg, rgba(0, 0, 0, 0) 0%, rgba(16, 11, 8, 0.86) 100%);
  pointer-events: none;
}

.category-icons__image-wrap {
  width: 100%;
  /* Portrait ratio matches the source product photos (~604x1075, 708x1259),
     so heads and legs are no longer cropped by `object-fit: cover`. */
  aspect-ratio: 3 / 5;
  height: auto;
  position: relative;
  border-radius: 2rem;
  overflow: hidden;
  flex-shrink: 0;
  background: rgba(var(--color-foreground), 0.04);
}

.category-icons__image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  /* Center focal point — previous values (center 38% / 40%) were pushing
     the visible window away from where the subjects actually are. */
  object-position: center center;
  display: block;
  transform: scale(1);
  transition: transform 0.28s ease;
}

.category-icons__image-wrap .placeholder-svg {
  width: 100%;
  height: 100%;
}

.category-icons__text {
  position: absolute;
  inset: auto 0 0;
  z-index: 4;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  margin: 0;
  padding: 3.4rem 1.15rem 1.15rem;
  color: #fff;
  text-align: left;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.42);
}

.category-icons__label {
  display: -webkit-box;
  overflow: hidden;
  margin: 0;
  font-size: 1.8rem;
  line-height: 1.12;
  font-weight: 800;
  letter-spacing: 0;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.category-icons__caption {
  display: block;
  max-width: 22rem;
  color: rgba(255, 255, 255, 0.88);
  font-size: 1.05rem;
  line-height: 1.25;
  font-weight: 600;
  letter-spacing: 0;
}

