    font-size: 1.18rem;
  }

  .section-category-icons .category-icons__group--category .category-icons__scroll {
    /* Tile geometry:
       - Small tiles (1 col × 1 row) ≈ 322×550px → ratio 0.59 ≈ portrait photo ratio (0.56)
       - Feature tiles (2 col × 2 rows) ≈ 668×1130px → ratio 0.59 ≈ portrait photo ratio
       Both tile sizes now closely match the source 0.56 product photos so
       `object-fit: cover` shows full outfits with minimal cropping. */
    --category-mosaic-row: clamp(34rem, 30vw, 46rem);
    --category-mosaic-feature-height: calc(var(--category-mosaic-row) * 2 + 2.4rem);
    grid-template-columns: repeat(4, minmax(0, 1fr));
    grid-template-rows: repeat(3, var(--category-mosaic-row));
  }

  .section-category-icons .category-icons__group--category .category-icons__item {
    min-height: 0;
  }

  .section-category-icons .category-icons__group--category .category-icons__link,
  .section-category-icons .category-icons__group--category .category-icons__image-wrap {
    height: 100%;
  }

  .section-category-icons .category-icons__group--category .category-icons__image-wrap {
    aspect-ratio: auto;
  }

  .section-category-icons .category-icons__group--category .category-icons__image-wrap img {
    /* Container ratio (≈0.59) now matches the photos (≈0.56), so center
       the focal point — only a tiny sliver gets cropped off either side. */
    object-position: center center;
  }

  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(1) {
    grid-column: 1 / 3;
    grid-row: 1 / 3;
  }

  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(2) {
    grid-column: 3 / 4;
    grid-row: 1 / 2;
  }

  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(3) {
    grid-column: 4 / 5;
    grid-row: 1 / 2;
  }

  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(4) {
    grid-column: 1 / 2;
    grid-row: 3 / 4;
  }

  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(5) {
    grid-column: 2 / 3;
    grid-row: 3 / 4;
  }

  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(6) {
    grid-column: 3 / 5;
    grid-row: 2 / 4;
  }

  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(1) .category-icons__link,
  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(6) .category-icons__link {
    height: var(--category-mosaic-feature-height);
  }

  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(n + 2):nth-child(-n + 5) .category-icons__link {
    height: var(--category-mosaic-row);
  }

  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(1) .category-icons__text,
  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(6) .category-icons__text {
    padding: 5.8rem 2rem 2rem;
  }

  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(1) .category-icons__label,
  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(6) .category-icons__label {
    font-size: 3.15rem;
    max-width: 13ch;
  }

  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(1) .category-icons__caption,
  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(6) .category-icons__caption {
    max-width: 28rem;
    font-size: 1.35rem;
  }

  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(n + 2):nth-child(-n + 5) .category-icons__text {
    padding: 3.25rem 1.2rem 1.2rem;
  }

  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(n + 2):nth-child(-n + 5) .category-icons__label {
    font-size: 1.68rem;
  }

  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(n + 2):nth-child(-n + 5) .category-icons__caption {
    font-size: 1.02rem;
  }

  .section-category-icons .category-icons__group--occasion .category-icons__image-wrap {
    /* Match portrait product photos so the full outfit is visible. */
    aspect-ratio: 3 / 5;
  }

  .section-category-icons .category-icons__group--occasion .category-icons__image-wrap img {
    /* Center focal point — old `center 40%` was clipping heads/legs. */
    object-position: center center;
  }

  .section-category-icons .category-icons__group--occasion .category-icons__text {
