.pagination__list {
  gap: 4px !important;
}
.pagination__list li a,
.pagination__list li span {
  font-size: 12px !important;
  font-weight: 600 !important;
  color: #666 !important;
  border-radius: 6px !important;
  padding: 8px 14px !important;
  transition: all 0.2s ease !important;
}
.pagination__list li a:hover {
  background: #f5f5f5 !important;
  color: #1a1a1a !important;
}
.pagination__list .pagination__item--current span,
.pagination__list li[aria-current] span {
  background: #1a1a1a !important;
  color: #fff !important;
  border-radius: 6px !important;
}

/* ================================================
   BREADCRUMBS — GLOBAL, EDITORIAL
   ================================================ */
.breadcrumbs,
nav.breadcrumb,
.breadcrumb {
  font-size: 11px !important;
  letter-spacing: 0.5px !important;
  text-transform: uppercase !important;
  color: #999 !important;
}
.breadcrumbs a,
.breadcrumb a {
  color: #999 !important;
  text-decoration: none !important;
}
.breadcrumbs a:hover,
.breadcrumb a:hover {
  color: #e85d3a !important;
}

/* ================================================
   GLOBAL SMOOTH SCROLL & SELECTION
   ================================================ */
html { scroll-behavior: smooth; }
::selection {
  background: rgba(232, 93, 58, 0.15);
  color: #1a1a1a;
}

/* Global link transitions */
a {
  transition: color 0.2s ease, opacity 0.2s ease;
}

/* ================================================
   MOBILE NAVIGATION — REFINED
   ================================================ */
@media screen and (max-width: 989px) {
  html.overflow-hidden-mobile,
  html.overflow-hidden-tablet,
  body.overflow-hidden-mobile,
  body.overflow-hidden-tablet {
    height: 100%;
