  .menu-drawer__main-item--parent > details[open] > .menu-drawer__menu-item--top-level {
    color: var(--mobile-menu-text) !important;
    background: rgba(255, 255, 255, 0.96) !important;
    box-shadow: 0 1.6rem 3.6rem rgba(76, 53, 40, 0.12) !important;
    transform: translateY(-1px);
  }

  .menu-drawer__menu-item--parent > .icon-arrow {
    display: none !important;
  }

  .menu-drawer__submenu {
    background: linear-gradient(180deg, #fdf9f4 0%, #f4ebe1 100%) !important;
  }

  .menu-drawer__inner-submenu {
