  }

  .menu-drawer__close-button {
    margin-top: 0 !important;
    min-height: 5rem;
    padding: 1.45rem 1.6rem !important;
    border: 1px solid var(--mobile-menu-card-border);
    border-radius: 1.6rem;
    background: rgba(255, 255, 255, 0.9) !important;
    box-shadow: 0 1rem 2.8rem rgba(76, 53, 40, 0.08);
    color: var(--mobile-menu-text) !important;
    font-size: 1.15rem !important;
    font-weight: 700 !important;
    letter-spacing: 0.18rem !important;
    text-transform: uppercase !important;
  }

  .menu-drawer__close-button .icon-arrow {
    width: 1.35rem;
    height: 1.35rem;
    margin-right: 1.2rem !important;
    color: var(--mobile-menu-muted);
  }

  .menu-drawer__submenu .menu-drawer__menu {
    display: grid;
    gap: 0.75rem;
    padding-top: 1.25rem;
  }

  .js .menu-drawer__submenu .menu-drawer__menu li {
    margin-bottom: 0 !important;
  }

  .menu-drawer__submenu .menu-drawer__menu-item {
    display: flex !important;
    align-items: center;
    min-height: 4.9rem;
    padding: 1.45rem 1.55rem !important;
    border: 1px solid var(--mobile-menu-card-border) !important;
