    color: var(--mobile-menu-text) !important;
    font-size: 1.45rem !important;
    font-weight: 600 !important;
    letter-spacing: 0 !important;
    text-decoration: none !important;
    text-transform: none !important;
  }

  .menu-drawer__account .icon-account {
    width: 1.85rem;
    height: 1.85rem;
    margin-right: 0 !important;
  }

  .menu-drawer__account shop-user-avatar {
    margin-right: 0 !important;
    margin-left: 0 !important;
  }

  .menu-drawer__localization {
    display: grid !important;
    gap: 0.85rem;
    margin-top: 0 !important;
  }

  .menu-drawer__localization localization-form {
    display: block;
  }

  .menu-drawer__localization .localization-form,
  .menu-drawer__localization .localization-form:only-child {
    width: 100%;
    padding: 0 !important;
    margin: 0 !important;
  }

  .menu-drawer__localization .localization-form__select,
  .menu-drawer__localization .localization-form:only-child .localization-form__select {
    width: 100%;
    margin: 0 !important;
  }

  .menu-drawer__localization .disclosure {
    width: 100%;
  }

  .menu-drawer__localization .disclosure__button.localization-form__select {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-height: 4.8rem;
    padding: 1.25rem 1.5rem !important;
    border: 1px solid var(--mobile-menu-card-border) !important;
    border-radius: 1.35rem !important;
    background: rgba(255, 255, 255, 0.72) !important;
    box-shadow: none !important;
    color: var(--mobile-menu-muted) !important;
    font-size: 1.24rem !important;
    font-weight: 600 !important;
    letter-spacing: 0.03rem !important;
  }

  .menu-drawer__localization .localization-form__select > span {
    display: block;
    max-width: calc(100% - 2.4rem);
    padding-right: 1.2rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .menu-drawer__localization .localization-form__select .icon-caret {
    position: static !important;
    width: 0.9rem;
    height: 0.9rem;
    margin-left: auto;
    color: var(--mobile-menu-muted);
    transform: none !important;
  }

  .menu-drawer .list-social {
    justify-content: center;
    gap: 0.55rem;
    margin: 1.25rem 0 0 !important;
  }

  .menu-drawer .list-social__link {
    display: grid;
    place-items: center;
    width: 4.2rem;
    height: 4.2rem;
    padding: 0 !important;
    border: 1px solid rgba(91, 65, 50, 0.1);
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.75);
    color: var(--mobile-menu-text) !important;
  }

  .menu-drawer__navigation a:hover,
  .menu-drawer__menu-item:hover {
    color: inherit !important;
  }
  /* Mobile hamburger icon */
  .header__icon--menu svg {
    width: 22px !important;
    height: 22px !important;
    color: #1a1a1a !important;
  }
  /* Mobile search */
  .header__search {
    border-radius: 50px !important;
    border: 1.5px solid #e0e0e0 !important;
  }
}

