/* ── Recently Viewed Products — lazy: only track on product pages, only render when empty cart containers exist ── */
(function() {
  const STORAGE_KEY = 'dlm_recently_viewed';
  const MAX_ITEMS = 6;

  function productPath(value) {
    if (typeof value !== 'string' || !value.startsWith('/')) return '';
    try {
      const url = new URL(value, window.location.origin);
      if (url.origin !== window.location.origin) return '';
      // Remove a previous language/market prefix before applying the active route root.
      const match = url.pathname.match(/^(?:\/[a-z]{2}(?:-[a-z]{2})?)?(\/products\/[^/]+)\/?$/i);
      return match ? match[1] : '';
    } catch (e) {
      return '';
    }
  }

  function imageUrl(value) {
    if (typeof value !== 'string' || !value.trim()) return '';
    try {
      const url = new URL(value, window.location.origin);
      return url.protocol === 'https:' || url.protocol === 'http:' ? url.href : '';
    } catch (e) {
      return '';
    }
  }

  function escapeHtml(value) {
    return value.replace(/[&<>"']/g, function(character) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character];
    });
  }

  function readRecentlyViewed() {
    try {
      const stored = JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
      if (!Array.isArray(stored)) return [];
      const seen = new Set();
      return stored.reduce(function(viewed, item) {
        const url = item && productPath(item.url);
        if (!url || typeof item.title !== 'string' || !item.title.trim() || seen.has(url)) return viewed;
        seen.add(url);
        viewed.push({ url, title: item.title, image: imageUrl(item.image), time: item.time });
        return viewed;
      }, []).slice(0, MAX_ITEMS);
    } catch (e) {
      return []; // Unavailable or malformed storage must not interrupt the cart.
    }
  }

  // Track current product page (lightweight — just localStorage write)
  const currentProductPath = productPath(window.location.pathname);
  if (currentProductPath) {
    try {
      const titleTag = document.querySelector('meta[property="og:title"]');
      const imageTag = document.querySelector('meta[property="og:image"]');

      if (titleTag) {
        const filtered = readRecentlyViewed().filter(item => item.url !== currentProductPath);
        filtered.unshift({ url: currentProductPath, title: titleTag.content || '', image: imageTag ? imageUrl(imageTag.content) : '', time: Date.now() });
        localStorage.setItem(STORAGE_KEY, JSON.stringify(filtered.slice(0, MAX_ITEMS)));
      }
    } catch(e) { /* localStorage not available */ }
  }

  // Only render if empty-cart containers exist on page
  function renderRecentlyViewed() {
    const drawerContainer = document.getElementById('CartDrawer-RecentlyViewed');
    const pageContainer = document.getElementById('CartPage-RecentlyViewed');
    if (!drawerContainer && !pageContainer) return; // No containers — skip entirely

    try {
      const viewed = readRecentlyViewed();
      if (viewed.length === 0) return;

      // Cached prices have no reliable currency/market context. The linked PDP owns current pricing.
      if (drawerContainer) {
        const drawerGrid = document.getElementById('CartDrawer-RecentlyViewedGrid');
        if (drawerGrid) {
          drawerGrid.innerHTML = viewed.slice(0, 3).map(function(item) {
            return '<a href="' + escapeHtml(getLocaleAwareRoute(item.url)) + '" class="cart-drawer__upsell-item">' +
              (item.image ? '<img src="' + escapeHtml(item.image) + '" alt="" width="70" height="70" loading="lazy" class="cart-drawer__upsell-img">' : '') +
              '<div class="cart-drawer__upsell-info"><span class="cart-drawer__upsell-name">' + escapeHtml(item.title.split(' | ')[0]) + '</span>' +
              '</div></a>';
          }).join('');
          drawerContainer.style.display = '';
        }
      }

      if (pageContainer) {
        const pageGrid = document.getElementById('CartPage-RecentlyViewedGrid');
        if (pageGrid) {
          pageGrid.innerHTML = viewed.slice(0, 4).map(function(item) {
            return '<a href="' + escapeHtml(getLocaleAwareRoute(item.url)) + '" class="cart-page__cross-sell-item">' +
              (item.image ? '<div class="cart-page__cross-sell-img-wrap"><img src="' + escapeHtml(item.image) + '" alt="" width="150" height="150" loading="lazy" class="cart-page__cross-sell-img"></div>' : '') +
              '<div class="cart-page__cross-sell-info"><span class="cart-page__cross-sell-name">' + escapeHtml(item.title.split(' | ')[0]) + '</span>' +
              '</div></a>';
          }).join('');
          pageContainer.style.display = '';
        }
      }
    } catch(e) { /* localStorage not available */ }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', renderRecentlyViewed);
  } else {
    renderRecentlyViewed();
  }

  // Quantity removal can replace the empty-cart markup after the initial page render.
  subscribe(PUB_SUB_EVENTS.cartUpdate, renderRecentlyViewed);
})();

/* ── Swipe-to-remove on mobile — only init on touch devices with cart items ── */
(function() {
  if (!('ontouchstart' in window)) return;
  if (!document.querySelector('.cart-item')) return; // No cart items — skip

  let startX = 0;
  let currentX = 0;
  let swiping = false;
  let currentRow = null;

  document.addEventListener('touchstart', function(e) {
    const row = e.target.closest('.cart-item');
    if (!row) return;
    startX = e.touches[0].clientX;
    currentRow = row;
    swiping = true;
  }, { passive: true });

  document.addEventListener('touchmove', function(e) {
    if (!swiping || !currentRow) return;
    currentX = e.touches[0].clientX;
    const diff = startX - currentX;
    if (diff > 10) {
      currentRow.style.transform = 'translateX(' + Math.max(-diff, -120) + 'px)';
      currentRow.style.transition = 'none';
    }
  }, { passive: true });

  document.addEventListener('touchend', function() {
    if (!swiping || !currentRow) return;
    const diff = startX - currentX;
    if (diff > 80) {
      // Swipe threshold met — remove item
      currentRow.style.transition = 'transform 0.3s ease, opacity 0.3s ease';
      currentRow.style.transform = 'translateX(-100%)';
      currentRow.style.opacity = '0';
      const removeBtn = currentRow.querySelector('cart-remove-button button, cart-remove-button a');
      if (removeBtn) {
        setTimeout(function() { removeBtn.click(); }, 300);
      }
    } else {
      // Reset position
      currentRow.style.transition = 'transform 0.2s ease';
      currentRow.style.transform = '';
    }
    swiping = false;
    currentRow = null;
  });
})();

/* Delivery estimate: hidden until checkout can confirm address-specific timing. */
/* Only runs when .js-delivery-date elements exist (cart has items) */
(function() {
  if (!document.querySelector('.js-delivery-date')) {
    // Defer — elements may appear later when cart drawer opens
    var checkLater = function() {
      if (document.querySelector('.js-delivery-date')) initDeliveryDates();
    };
    document.addEventListener('cart:updated', checkLater);
    var drawer = document.getElementById('CartDrawer');
    if (drawer) {
      new MutationObserver(function(mutations) {
        if (document.querySelector('.js-delivery-date:empty')) initDeliveryDates();
      }).observe(drawer, { childList: true, subtree: true });
    }
    return;
  }
  initDeliveryDates();

  function initDeliveryDates() {
  function setDeliveryContainerVisibility(dateElement, isVisible) {
    if (!dateElement) return;

    const container = dateElement.closest('.cart-page__delivery-estimate, .cart-drawer__checkout-reassurance');
    if (container) {
      container.hidden = !isVisible;
    }
  }

  function updateDeliveryDates() {
    document.querySelectorAll('.js-delivery-date').forEach(function(el) {
      el.textContent = '';
      setDeliveryContainerVisibility(el, false);
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', updateDeliveryDates);
  } else {
    updateDeliveryDates();
  }

  // Also update after AJAX cart updates (drawer re-renders)
  document.addEventListener('cart:updated', updateDeliveryDates);
  const observer = new MutationObserver(function(mutations) {
    mutations.forEach(function(m) {
      if (m.addedNodes.length) {
        const hasDate = document.querySelector('.js-delivery-date:empty');
        if (hasDate) updateDeliveryDates();
      }
    });
  });
  const cartDrawer = document.getElementById('CartDrawer');
  if (cartDrawer) observer.observe(cartDrawer, { childList: true, subtree: true });
  } /* end initDeliveryDates */
})();

