  .section-category-icons .category-icons__group--category .category-icons__scroll {
    /* Tile geometry:
       - Small tiles (1 col × 1 row) ≈ 322×550px → ratio 0.59 ≈ portrait photo ratio (0.56)
       - Feature tiles (2 col × 2 rows) ≈ 668×1130px → ratio 0.59 ≈ portrait photo ratio
       Both tile sizes now closely match the source 0.56 product photos so
       `object-fit: cover` shows full outfits with minimal cropping. */
    --category-mosaic-row: clamp(34rem, 30vw, 46rem);
    --category-mosaic-feature-height: calc(var(--category-mosaic-row) * 2 + 2.4rem);
    grid-template-columns: repeat(4, minmax(0, 1fr));
