    /* Container ratio (≈0.59) now matches the photos (≈0.56), so center
       the focal point — only a tiny sliver gets cropped off either side. */
    object-position: center center;
  }

  .section-category-icons .category-icons__group--category .category-icons__item:nth-child(1) {
    grid-column: 1 / 3;
    grid-row: 1 / 3;
