{% schema %}
{
  "name": "Category Icons",
  "tag": "section",
  "class": "section section-category-icons",
  "disabled_on": {
    "groups": ["header", "footer"]
  },
  "max_blocks": 12,
  "settings": [
    {
      "type": "inline_richtext",
      "id": "title",
      "label": "Heading"
    },
    {
      "type": "select",
      "id": "heading_size",
      "options": [
        { "value": "h2", "label": "Small" },
        { "value": "h1", "label": "Medium" },
        { "value": "h0", "label": "Large" }
      ],
      "default": "h2",
      "label": "Heading size"
    },
    {
      "type": "select",
      "id": "display_mode",
      "options": [
        { "value": "single", "label": "Single path" },
        { "value": "grouped", "label": "Group by category and occasion" }
      ],
      "default": "single",
      "label": "Layout"
    },
    {
      "type": "text",
      "id": "category_heading",
      "default": "Shop by category",
      "label": "Category heading"
    },
    {
      "type": "url",
      "id": "category_heading_link",
