        }
      ],
      "default": "h2",
      "label": "Heading size"
    },
    {
      "type": "richtext",
      "id": "intro",
      "label": "Intro"
    },
    {
      "type": "richtext",
      "id": "supporting_note",
      "label": "Condensed trust note"
    },
    {
      "type": "text",
      "id": "button_label",
      "default": "Shop all family sets",
      "label": "Button label"
    },
    {
      "type": "url",
      "id": "button_link",
      "label": "Button link"
    },
    {
      "type": "color_scheme",
      "id": "color_scheme",
      "default": "scheme-1",
      "label": "Color scheme"
    },
    {
      "type": "color",
      "id": "card_background",
      "default": "#FFFDFC",
      "label": "Card background"
    },
    {
      "type": "color",
      "id": "accent_color",
      "default": "#C87932",
      "label": "Accent color"
    },
    {
      "type": "text",
      "id": "footer_heading",
      "label": "Footer heading"
    },
    {
      "type": "richtext",
      "id": "footer_body",
      "label": "Footer body"
    },
    {
      "type": "range",
      "id": "padding_top",
      "min": 0,
      "max": 120,
      "step": 4,
      "default": 24,
      "unit": "px",
      "label": "Padding top"
    },
    {
      "type": "range",
      "id": "padding_bottom",
      "min": 0,
      "max": 120,
      "step": 4,
      "default": 32,
      "unit": "px",
      "label": "Padding bottom"
    }
  ],
  "blocks": [
    {
      "type": "product_card",
      "name": "Product card",
      "settings": [
        {
          "type": "product",
          "id": "product",
          "label": "Product"
        },
        {
          "type": "text",
          "id": "badge",
          "default": "Most loved",
          "label": "Badge"
        },
        {
          "type": "textarea",
          "id": "caption",
          "default": "Use this slot for the products shoppers engage with most before purchase.",
          "label": "Caption"
        },
        {
          "type": "text",
          "id": "button_label",
          "default": "Shop This Look",
          "label": "Button label"
        },
        {
          "type": "collection",
          "id": "secondary_collection",
          "label": "Secondary collection link"
        },
        {
          "type": "text",
          "id": "collection_link_label",
